"""Original implementation playbooks and browser-only planning tools."""
from html import escape as e
import json

DATE = '2026-10-24'
ROOT = '/ai/implementation/'
# Each record owns a different deliverable, rather than a variation of a keyword.
COLLECTIONS = [
('agents-and-integrations', 'AI Agents and Integrations', 'Design bounded agents that can use business tools, recover from failures, and leave a useful record.', [
('workflow-or-agent', 'AI Workflow or AI Agent: Choose the Right Architecture', 'An architecture decision record', 'A customer onboarding process with intake, validation, account creation, and welcome email.', 'List the steps whose sequence is known. Use a fixed workflow for those steps. Give an agent only the ambiguous part, such as identifying missing intake details; return its result to a validated workflow.', 'Draw the current process with its inputs and exit conditions.|Mark which branches require interpretation and which follow a rule.|Build the simplest version with one model call for the ambiguous step.|Compare completion, corrections, latency, and cost with a deterministic alternative.', 'Use a form missing its billing contact. The system should request the missing information and stop before account creation. A complete form should follow the fixed path without extra reasoning loops.', 'Choosing an agent because it sounds more advanced creates more decisions to test. If a rules-based branch handles the input reliably, retain it.', 'Write an architecture decision record for this process. Separate deterministic steps from interpretation. Specify inputs, output schema, stop conditions, permissions, and a simpler alternative. Do not assume integrations exist.'),
('agent-tool-contracts', 'Write Tool Contracts Before Connecting an AI Agent', 'A tool specification with validation rules', 'A CRM lookup tool and a task creation tool for preparing sales follow-ups.', 'Describe every tool as a contract: accepted fields, required identifiers, allowed values, return fields, failure states, and whether the operation changes external data. Validate these properties in code outside the model.', 'Start with a read-only lookup and sample response.|Use stable customer IDs instead of fuzzy names for mutations.|Reject missing fields and unsupported status values before execution.|Return machine-readable success and error results with a request ID.', 'Supply two contacts with the same name. The agent should request the correct identifier, rather than guess. Give an invalid due date and confirm the tool rejects it.', 'A descriptive prompt is not an authorization system. Enforce access and field validation in the tool service.', 'Draft a contract for this tool: purpose, typed inputs, preconditions, side effects, response fields, and errors. Include one valid request and three rejected requests. Identify the permission boundary.'),
('idempotency-and-retries', 'Prevent Duplicate Actions in AI Automations', 'A retry and duplicate-prevention plan', 'A scheduled assistant that creates a follow-up task after an approved sales call.', 'A timeout does not prove that an action failed. Assign a durable operation key to the business event and store the outcome so a retry can recover the existing result instead of creating a second task.', 'Choose a key from event ID, action type, and intended version.|Persist the key before attempting the external action.|Use provider idempotency support or a durable action ledger.|Retry transient failures with a bounded policy; send uncertain outcomes to review.', 'Simulate a task created successfully followed by a network timeout. Retrying the same event should find the original task. A revised approved action should use a new explicit version.', 'Checking a text log after an action leaves a race window. Use transactional storage or provider support appropriate to the system.', 'Design a retry policy for this action. Define the operation key, durable states, timeout recovery, retry limits, and manual resolution path. Show how two concurrent requests avoid duplicate work.'),
('human-approval-inbox', 'Design an Approval Inbox for AI-Proposed Actions', 'An approval record tied to an exact proposed action', 'An assistant drafting a customer email and proposing a CRM stage change.', 'Show the reviewer the recipient, exact message, record ID, proposed changes, evidence, and expiry. Approval must apply to that snapshot. Editing the action or changing the underlying record invalidates the approval.', 'Separate draft preparation from execution permissions.|Store a version or hash of the complete action payload.|Require an authenticated reviewer with authority for the action.|Recheck approval, record version, and expiry immediately before execution.', 'Approve an email draft, then change the recipient or price. The system should require a fresh approval. Test expired approval and a reviewer without the required role.', 'A generic approve button can authorize an action the reviewer never saw. Bind the decision to the displayed payload.', 'Create an approval-inbox specification for these actions. Include what the reviewer sees, who may approve, expiry, edit invalidation, execution checks, and an audit record.'),
('agent-runbooks', 'Create an AI Agent Failure and Recovery Runbook', 'An operator runbook for interrupted automation', 'An internal research assistant whose document search service becomes unavailable halfway through a run.', 'Distinguish source outages, model errors, invalid output, permission failures, and uncertain external writes. Each needs a different recovery path. Keep enough state to resume safely without replaying completed mutations.', 'Record a run ID and a checkpoint after each accepted step.|Set time, tool-call, and spending limits.|Map error types to retry, fallback, stop, or human review.|Give operators a safe stop control and a documented resume procedure.', 'Disconnect retrieval after two successful lookups. The output should disclose incomplete coverage and preserve the completed work. Resume should not repeat already completed external actions.', 'Returning a confident final answer from a partially failed run hides missing work. Surface incomplete coverage in both the status and deliverable.', 'Write a recovery runbook for this workflow with failure classes, alerts, retained state, retry limits, safe stop, resume checks, and the named operator role.'),
('agent-observability', 'Track AI Agent Quality, Cost, and Business Outcomes', 'A run-level operating dashboard specification', 'A document preparation assistant with source search, drafting, and reviewer approval.', 'Measure the path from request to accepted output. Token cost and draft speed alone miss retries, reviewer effort, and abandoned runs. Connect technical events to a stable business task identifier.', 'Log run status, durations, source versions, and tool results.|Record review minutes, corrections, and acceptance outcome.|Aggregate cost per accepted deliverable, not per generated draft.|Set alerts for rising rejection, latency, failures, and missing telemetry.', 'Create one fast rejected draft and one slower accepted draft. The dashboard should not rank the rejected draft as a success. Confirm that retry costs remain attached to the original task.', 'Storing entire prompts may expose unnecessary customer data. Keep structured operational metadata and apply a deliberate retention policy.', 'Specify an AI operations dashboard with metric definitions, event fields, aggregation rules, owner, and alert thresholds. Include cost per accepted output and reviewer time.')
]),
('knowledge-and-evaluation', 'AI Knowledge Bases and Evaluation', 'Build source-grounded answers and test the failure cases before a team depends on them.', [
('knowledge-source-register', 'Build a Source Register for an AI Knowledge Base', 'A register of approved source documents', 'An internal assistant answering questions about service policies across several departments.', 'Before indexing, identify the authoritative document, owner, effective date, access group, and retirement rule for each policy. Conflicting copies require an owner decision before the assistant uses them.', 'Inventory documents by business question rather than file count.|Assign source authority and a review owner.|Remove superseded copies from the active collection.|Record approval and expiry with the index version.', 'Provide two refund policies with different effective dates and no clear approval status. The assistant should flag the conflict rather than choose the more generous policy.', 'More documents can reduce answer reliability when authority is unclear. Resolve conflicts at the source.', 'Create a source register with document ID, title, owner, effective date, audience, authority, review date, and superseded-by field. List unresolved conflicts separately.'),
('retrieval-permissions', 'Keep Knowledge Base Answers Within User Permissions', 'An access-aware retrieval test plan', 'A company assistant with general policies and restricted management documents.', 'Apply access filtering before retrieved text reaches the model. The answer must reflect the authenticated user’s permissions, including cached responses and any linked source passages.', 'Carry verified user identity into the retrieval service.|Filter documents and passages using current access groups.|Scope caches to permissions and source versions.|Test access removal and links as well as normal search.', 'Ask a general employee for an executive-only document by exact title, then revoke access for a previously authorized user. Neither cached text nor source links should reveal restricted content.', 'Asking the model to hide a restricted passage is too late if that passage already entered its context.', 'Write a retrieval permission test plan covering identity, group membership, filtering, caches, revocation, source links, and audit evidence. Include denied-access cases.'),
('citation-verification', 'Test Whether an AI Answer Is Supported by Its Citations', 'A claim-to-evidence review sheet', 'An assistant answering a question about service coverage from an approved handbook.', 'A citation can be real while failing to support the statement beside it. Split the answer into factual claims and compare each claim with the cited passage, including qualifiers and effective dates.', 'Assign a claim ID to each material statement.|Capture the exact supporting passage and document version.|Mark support as full, partial, absent, or contradicted.|Remove or qualify claims without sufficient evidence.', 'Use a source that says weekend support is available only on the premium plan. An answer promising weekend support to every customer must fail, even with the correct source link.', 'Counting citations is not evidence verification. Review whether the passage entails the specific statement.', 'Create a claim-to-evidence table for this answer. Preserve plan restrictions, dates, and exceptions. Label unsupported claims and propose a corrected answer using only supplied passages.'),
('evaluation-dataset-design', 'Build a Representative AI Workflow Evaluation Dataset', 'A versioned test set with acceptance criteria', 'A service intake classifier used across several customer request types.', 'Define success before selecting examples. Include routine cases, ambiguous requests, missing data, and cases that must be escalated. Separate development examples from held-out cases used to decide whether to release.', 'Sample completed tasks across categories and time periods.|Remove unnecessary personal data and retain the needed context.|Have qualified reviewers label expected output and unacceptable errors.|Version the set and reserve cases that prompt authors do not tune against.', 'Add a request containing both a billing complaint and a service outage. Decide in advance whether it needs multiple labels or escalation, then assess the classifier consistently.', 'A test set containing only clean examples exaggerates performance. Report results by case type and severity.', 'Design an evaluation dataset specification for this workflow. Include sampling, labels, edge cases, reviewer disagreement, held-out cases, versioning, and release criteria.'),
('model-change-regression', 'Run Regression Checks Before Changing an AI Model', 'A release comparison and rollback decision', 'A working extraction assistant migrating to a different model or prompt version.', 'Treat a model, prompt, retrieval, or tool change as a release. Replay a fixed test set and compare both quality and operating cost, then use a limited live rollout with a rollback path.', 'Freeze the current prompt, model settings, tools, and source version.|Run old and new versions on the same cases.|Compare field accuracy, critical failures, latency, and total cost.|Release to a bounded group and monitor before expanding.', 'The new version is faster overall but misses a cancellation clause in a critical case. The release should fail the critical-error gate despite a higher average score.', 'A single overall score can hide a severe regression in a small category. Keep critical error gates explicit.', 'Draft a regression report template comparing baseline and candidate versions. Define critical-error gates, subgroup results, operating costs, rollout limits, and rollback triggers.'),
('abstention-and-escalation', 'Teach an AI Assistant When to Say It Does Not Know', 'An abstention and escalation policy', 'An employee assistant receiving questions outside the approved policy collection.', 'Define the evidence needed to answer and the conditions that require clarification or escalation. The goal is a useful next step when evidence is missing, rather than a plausible unsupported answer.', 'List the answerable question types and required sources.|Define missing-source, conflict, and out-of-scope conditions.|Provide a short escalation message and destination role.|Measure both unsupported answers and unnecessary abstentions.', 'Ask about a policy never included in the source set, then ask a valid question with a clear passage. The assistant should escalate the first and answer the second with evidence.', 'An assistant that refuses every question may appear safe while providing no operational value. Track useful completion alongside unsupported answers.', 'Write an answer, clarify, or escalate decision policy for this assistant. Include source requirements, conflicting evidence, missing details, escalation ownership, and example responses.')
]),
('content-and-rollout', 'AI Content Operations and Team Rollout', 'Turn source material into useful publishing systems and a measured adoption plan.', [
('content-evidence-ledger', 'Build an Evidence Ledger for AI-Assisted Content', 'A publication-ready claim and source ledger', 'A long-form article assembled from interviews, internal notes, and public documentation.', 'Separate the topic outline from the evidence ledger. Every factual claim needs a source, date checked, scope, and publication permission where applicable. Opinions and examples should be labeled so they do not become invented results.', 'Extract factual claims from the working outline.|Attach original sources and the relevant passage.|Verify figures, names, dates, and claimed outcomes.|Remove unsupported claims before the editorial review.', 'A draft says a workflow saved 40 percent of team time, but the interview only says it felt faster. Remove the number or replace it with a clearly attributed qualitative observation.', 'A confident narrative can turn an anecdote into a measured result. The ledger preserves the distinction.', 'Create an evidence ledger for this draft: claim, source, passage, date checked, scope, permission status, and action needed. Do not add sources or statistics that were not provided.'),
('interview-to-content-system', 'Turn Expert Interviews Into a Reliable AI Content System', 'An interview-derived editorial package', 'A recorded conversation explaining an operator’s approach to customer onboarding.', 'Start with the transcript and the expert’s actual examples. Extract decisions, constraints, and stories before choosing article formats. Confirm interpretations with the expert and preserve a link from each draft back to its source.', 'Confirm recording and publication permission.|Mark transcript passages by theme and timestamp.|Create one article outline and channel-specific derivatives.|Have the expert verify quotations and interpretation before publication.', 'A speaker describes one client exception. The resulting article should not present it as a universal company policy. Link the passage and ask the expert to confirm the scope.', 'Generating more derivative posts does not create more evidence. Keep each derivative tied to the original conversation.', 'From this transcript, create a theme map with timestamps, an article outline, and three short post drafts. Preserve the speaker’s qualifications. Mark unclear quotes for confirmation.'),
('content-refresh-triage', 'Prioritize Content Updates With an AI Editorial Review', 'A ranked content refresh backlog', 'A library of business articles with analytics exports, publication dates, and existing source links.', 'Identify which pages have a reader problem: outdated instructions, weak evidence, incomplete coverage, or unclear next steps. Use analytics to locate candidates, then inspect the content before deciding to rewrite, merge, or leave it alone.', 'Export page-level performance for comparable periods.|Check seasonality and tracking changes before inferring decay.|Review sources and reader intent on candidate pages.|Assign a specific update, owner, and verification method.', 'A seasonal page falls after its peak month while a core guide contains a broken process. Prioritize the broken guide rather than equating every traffic decline with content failure.', 'Traffic movement alone does not identify the cause. Record competing explanations and the evidence needed to distinguish them.', 'Build a content refresh backlog from these exports and page notes. Separate observed changes from hypotheses. Recommend update, consolidate, investigate, or retain, with evidence and an owner.'),
('thirty-day-ai-rollout', 'A 30-Day AI Workflow Rollout Plan for a Small Team', 'A four-week rollout plan with release gates', 'A five-person team testing an internal meeting brief assistant.', 'Use the month to prove one accepted workflow. Allocate time for baseline measurement, test cases, user practice, and review rather than trying to introduce multiple unrelated assistants simultaneously.', 'Week 1: define the task, baseline, source owner, and acceptance checklist.|Week 2: build a draft-only pilot and test routine and exception cases.|Week 3: train a bounded user group and log corrections and review time.|Week 4: compare accepted outputs with baseline and decide expand, revise, or stop.', 'The pilot drafts quickly but shifts an hour of cleanup onto the manager. Count that time and revise the workflow before expanding to the whole company.', 'A rollout calendar is not proof of readiness. Each week should end with evidence and a decision gate.', 'Create a 30-day rollout plan for this single workflow. Include weekly deliverables, owners, review capacity, baseline, exception tests, acceptance criteria, and a final expand/revise/stop decision.'),
('ai-workflow-ownership', 'Assign Ownership for AI Workflows After the Pilot', 'An operating ownership and maintenance register', 'A successful assistant whose prompt author is moving to another role.', 'Name separate responsibilities for the business outcome, source accuracy, technical operation, and final review. One person may hold several roles, but each responsibility needs a backup and a maintenance trigger.', 'Register each live workflow and its business owner.|Assign source, prompt, integration, and review responsibilities.|Document access, runbook, version history, and retirement conditions.|Schedule reviews after source changes, incidents, or staff transitions.', 'A service policy changes while the assistant owner is unavailable. The backup should know how to pause the workflow, update the source, run regression checks, and restore service.', 'Ownership assigned only to the person who built the prompt often disappears at the first staff change.', 'Create an ownership register for these workflows with accountable owner, backup, source steward, technical operator, reviewer, review triggers, and retirement procedure.'),
('ai-procurement-scorecard', 'Use a Task-Based Scorecard to Evaluate AI Vendors', 'A vendor trial and purchasing decision sheet', 'A team choosing between tools for an approved document extraction workflow.', 'Compare vendors on the same task, source set, expected outputs, and operating constraints. Record observed trial results separately from sales claims and unknown contractual terms.', 'Write must-have requirements before viewing demos.|Run identical approved examples and exception cases.|Measure accepted quality, reviewer effort, integration fit, and full cost.|Confirm access controls, export options, support, and exit requirements.', 'One vendor wins a polished demo but cannot export source references required by reviewers. Mark the must-have as failed rather than compensating with attractive optional features.', 'A weighted score can hide a failed essential requirement. Apply must-have gates before ranking the remaining options.', 'Create a vendor scorecard for this task with must-have gates, weighted preferences, test evidence, unknowns, total-cost inputs, and an exit plan. Keep sales claims separate from observed results.')
])]

STYLE = '''<style>.impl-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:22px;margin:28px 0}.impl-card{border:1px solid var(--border,#ddd);border-radius:12px;padding:24px}.impl-card h3{margin-top:0}.impl-content{max-width:880px}.impl-content h2{margin-top:36px}.impl-content li{margin-bottom:12px}.impl-content pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:22px;background:#f3f4f6;color:#17202a;border-radius:8px}.impl-content label{display:block;margin:18px 0}.impl-content input{display:block;width:100%;max-width:400px;padding:12px;font:inherit;border:1px solid #888;border-radius:6px}.impl-result{padding:24px;border:1px solid var(--border,#ddd);border-radius:10px;margin:24px 0}.impl-content button{padding:12px 20px;font:inherit;cursor:pointer}</style>'''

def render_pages(header, breadcrumbs, footer, site_url, person_id):
    pages = {}
    def wrap(title, desc, path, body, kind='WebPage', article=False):
        crumbs = [('Home', '/'), ('AI Business Strategy', '/ai-business-strategy/'), ('AI Implementation Library', ROOT)]
        if path == ROOT:
            crumbs[-1] = ('AI Implementation Library', None)
        else:
            crumbs.append((title, None))
        nodes = []
        if article:
            nodes = [{'@type':'TechArticle', 'headline':title, 'author':{'@id':person_id}, 'datePublished':DATE, 'dateModified':DATE, 'mainEntityOfPage':site_url+path}]
        return header(title, desc, path, page_type=kind, crumbs=crumbs, schema_nodes=nodes, extra=STYLE) + breadcrumbs(crumbs) + f'<section class="pg-hero"><div class="ctn"><h1>{e(title)}</h1><p>{e(desc)}</p></div></section><section class="sec"><div class="ctn impl-content">{body}</div></section>' + footer()
    def card(title, path, desc):
        return f'<div class="impl-card"><h3><a href="{path}">{e(title)}</a></h3><p>{e(desc)}</p></div>'
    hubs = ''
    for slug, title, desc, guides in COLLECTIONS:
        hub = ROOT+slug+'/'
        hubs += card(title, hub, desc)
        cards = ''.join(card(g[1], hub+g[0]+'/', g[2]+'.') for g in guides)
        pages[hub] = wrap(title, desc, hub, '<p>Choose the deliverable your team needs. Each playbook includes a method, a worked scenario, a failure case, and a reusable prompt.</p><div class="impl-grid">'+cards+'</div><p><a href="'+ROOT+'templates/">Get the implementation templates</a> and <a href="'+ROOT+'roi-calculator/">estimate the economics</a> before committing to a rollout.</p>', 'CollectionPage')
        for i, g in enumerate(guides):
            gs, gt, outcome, scenario, method, steps, trial, mistake, prompt = g
            path = hub+gs+'/'
            sequence = ''.join('<li>'+e(s)+'</li>' for s in steps.split('|'))
            related = ''.join('<li><a href="'+hub+other[0]+'/">'+e(other[1])+'</a></li>' for other in [guides[(i+1)%len(guides)], guides[(i+2)%len(guides)]])
            body = f'''<p>By <a href="/about/">Dr. Connor Robertson</a> · Published October 24, 2026 · Implementation playbook</p>
<p><strong>Deliverable:</strong> {e(outcome)}. Use this playbook when your team needs a repeatable operating decision with evidence that another person can inspect.</p>
<h2>The business situation</h2><p>{e(scenario)} This is an illustrative scenario, not a reported client result. Start with a small approved sample and the actual constraints of your team.</p>
<h2>The operating approach</h2><p>{e(method)}</p><h2>Build it step by step</h2><ol>{sequence}</ol>
<h2>A concrete acceptance test</h2><p>{e(trial)}</p><p>Record the input, expected behavior, actual result, reviewer, and version tested. Repeat this case after a prompt, source, model, or integration change. Include the cases that failed in the next regression run.</p>
<h2>The mistake to avoid</h2><p>{e(mistake)}</p><h2>A reusable working prompt</h2><pre>{e(prompt)}</pre>
<p>Replace general descriptions with your approved process details. The prompt helps prepare an artifact; the process owner verifies the finished result before it changes a live workflow.</p>
<h2>What to keep in the handoff</h2><p>Save the accepted {e(outcome.lower())}, its source versions, test evidence, unresolved questions, and a named owner. Set a review trigger tied to a meaningful business change, rather than leaving the pilot without maintenance.</p>
<h2>Continue implementation</h2><ul>{related}<li><a href="{ROOT}templates/">Copy the implementation templates</a></li><li><a href="{ROOT}roi-calculator/">Calculate review-adjusted AI ROI</a></li></ul><p><a href="{hub}">Explore {e(title)}</a> or <a href="/contact/">contact Dr. Connor Robertson</a> about your business workflow.</p>'''
            pages[path] = wrap(gt, outcome+' for a practical business AI workflow, with steps, an acceptance test, and a reusable prompt.', path, body, article=True)
    body = '''<p>Move from a useful AI draft to a workflow your team can operate. This library adds 18 implementation playbooks across architecture, knowledge quality, content publishing, and team adoption. Start with the deliverable you need, then use the templates to make the decision reviewable.</p><h2>Find the right guide</h2><p><a href="/ai/implementation/directory/">Search all 92 AI guides</a>, explore <a href="/ai/implementation/industries/">eight industry implementation plans</a>, compare <a href="/ai/implementation/decisions/">six architecture choices</a>, or use the <a href="/ai/implementation/glossary/">business AI glossary</a>. Start with the <a href="/ai/implementation/readiness-planner/">pilot readiness planner</a> when ownership, evidence, or acceptance criteria are still unclear.</p><h2>Choose your next operating problem</h2><div class="impl-grid">'''+hubs+'''</div><h2>Planning tools</h2><div class="impl-grid">'''+card('AI Workflow ROI Calculator', ROOT+'roi-calculator/', 'Estimate net monthly capacity value after review, rework, subscriptions, and setup cost.')+card('AI Implementation Templates', ROOT+'templates/', 'Copy a pilot charter, evaluation record, approval specification, and release checklist.')+'''</div><h2>Start with existing task guides</h2><p>For a first draft or a single task, explore <a href="/ai/chatgpt-business-workflows/">ChatGPT workflows</a>, <a href="/ai/claude-business-documents/">Claude document workflows</a>, <a href="/ai/custom-gpts-business/">custom GPT systems</a>, <a href="/ai/ai-department-playbooks/">department playbooks</a>, and <a href="/ai/ai-governance-measurement/">governance and measurement</a>.</p><h2>Further technical reading</h2><p>For the workflow-versus-agent distinction, see <a href="https://www.anthropic.com/research/building-effective-agents">Anthropic’s agent architecture guide</a>. For evaluation methodology, see <a href="https://developers.openai.com/learn/evals">OpenAI’s evaluation resources</a>. The playbooks here are original operating templates; illustrative examples are not client performance claims.</p>'''
    body += '<h2>Work with a tested example</h2><p><a href="/guides/customer-question-csv-to-faq-brief/">Turn customer-question CSV files into evidence-backed FAQ briefs</a>, with a local Python utility, synthetic inputs and expected output.</p>'
    pages[ROOT] = wrap('AI Implementation Library', 'Practical AI implementation playbooks, planning templates, and an ROI calculator for business owners and operators.', ROOT, body, 'CollectionPage')
    pages[ROOT+'templates/'] = wrap('AI Implementation Templates', 'Copy practical templates for an AI pilot, evaluation record, approval gate, and workflow release.', ROOT+'templates/', templates())
    pages[ROOT+'roi-calculator/'] = wrap('AI Workflow ROI Calculator', 'Estimate AI workflow economics after human review, rework, software costs, and implementation time.', ROOT+'roi-calculator/', calculator())
    return pages

def templates():
    records = [
('Pilot charter', 'Business task:\nDeliverable and required fields:\nBusiness owner and backup:\nBaseline sample and measured time:\nApproved sources and versions:\nAllowed data and access:\nPilot users and review capacity:\nAcceptance criteria and critical errors:\nPilot dates and decision date:\nDecision: expand / revise / stop'),
('Evaluation record', 'Case ID and category:\nInput and source version:\nExpected result:\nUnacceptable error:\nPrompt, model, and tool versions:\nActual output:\nReviewer and decision:\nPreparation / generation / review / rework minutes:\nFailure cause and correction:\nRegression case added: yes / no'),
('Approval specification', 'Action and exact payload:\nRecipient or target record ID:\nEvidence shown to reviewer:\nAuthorized reviewer role:\nPayload version or hash:\nApproval expiry:\nChanges that invalidate approval:\nRecord version check before execution:\nIdempotency key and execution record:\nFailure and manual resolution path:'),
('Release checklist', '[ ] Source owner approved current material\n[ ] Routine, missing-data, conflict, and failure cases tested\n[ ] Critical errors meet the release standard\n[ ] Permissions and denied-access cases checked\n[ ] Review capacity assigned\n[ ] Retry and duplicate handling verified where relevant\n[ ] Baseline and full operating cost recorded\n[ ] Limited rollout and rollback plan documented\n[ ] Owner, backup, and maintenance triggers assigned\n[ ] Expand / revise / stop decision recorded')]
    return '<p>Copy these templates into your team’s working document. Complete the fields with observed evidence; a filled-in form does not establish that a workflow is ready.</p>'+''.join(f'<h2>{e(t)}</h2><pre>{e(v)}</pre>' for t,v in records)+'<p>Use the <a href="'+ROOT+'content-and-rollout/thirty-day-ai-rollout/">30-day rollout plan</a> to sequence the work.</p>'

def calculator():
    fields = [('volume','Tasks per month',200),('before','Manual minutes per task',20),('draft','AI preparation and drafting minutes per task',5),('review','Human review minutes per task',4),('rework','Average rework minutes per task, including rejected drafts',2),('rate','Loaded hourly labor cost ($)',50),('software','Monthly software and usage cost ($)',150),('setup','One-time implementation cost ($)',1500)]
    form = ''.join(f'<label for="roi-{key}">{label}<input id="roi-{key}" name="{key}" type="number" min="0" max="100000000" step="any" value="{value}" required></label>' for key,label,value in fields)
    return '''<p>This calculator values time released for other work. It does not predict revenue or cash savings. Use observed average time across all attempted tasks, including rejected drafts and manual fallback. Add training and integration work to setup cost.</p><form id="roi-form">'''+form+'''<button type="submit">Calculate estimate</button></form><noscript><p>JavaScript is required for the interactive calculation. Monthly net value = tasks × (manual minutes − preparation − review − rework) ÷ 60 × hourly cost − software. Payback months = setup cost ÷ positive monthly net value.</p></noscript><div id="roi-result" class="impl-result" role="status" aria-live="polite"></div><h2>Read the estimate carefully</h2><p>Monthly net value subtracts recurring software from the labor value of time released. Setup cost is included in first-year value and simple payback. Negative time released means the proposed workflow takes more work than the baseline. If monthly net value is zero or negative, there is no positive simple payback.</p><p>The tool runs in your browser and does not send these inputs to a server. Record actual accepted-output quality alongside this estimate; faster inaccurate work is not a successful pilot.</p><p><a href="/ai/ai-governance-measurement/measure-ai-workflow-roi-human-review/">Read the AI ROI measurement guide</a> and <a href="/ai/implementation/templates/">copy the pilot charter</a>.</p><script>
(function(){const form=document.getElementById('roi-form'),out=document.getElementById('roi-result');function calculate(event){if(event)event.preventDefault();if(!form.reportValidity())return;const n={};for(const [key,value] of new FormData(form))n[key]=Number(value);if(Object.values(n).some(v=>!Number.isFinite(v)||v<0)){out.textContent='Enter a finite, nonnegative number in every field.';return;}const hours=n.volume*(n.before-n.draft-n.review-n.rework)/60,net=hours*n.rate-n.software;const money=v=>v.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});out.textContent='Estimated time released: '+hours.toFixed(1)+' hours/month. Net monthly capacity value: '+money(net)+'. First-year value after setup: '+money(net*12-n.setup)+'. Simple payback: '+(net>0?(n.setup/net).toFixed(1)+' months.':'No positive payback at these inputs.');}form.addEventListener('submit',calculate);calculate();})();
</script>'''
